"},{"ref":"src/server/business/contracts.ts","hash":"072f05e8a4ee3fcec2c98a863de5fd3e3158e6ab2cce9f21696c2dd3d1274081","content":"export type WorkflowId = string;
export type Task = {
  id: string;
  title: string;
  description: string;
  state: string;
  revision: number;
  createdAt: string;
  updatedAt: string;
  deletedAt: string | null;
  fields: Record<string, string>;
};
export type Field = {
  key: string;
  label: string;
  type: "text";
  required?: boolean;
  description?: string;
  providerId?: string;
};
export type Action = {
  id: string;
  label: string;
  from: string[];
  providerId?: string;
};
export type WorkflowDefinition = {
  id: WorkflowId;
  name: string;
  version: string;
  initialState: string;
  states: Record<string, { label: string; category: "open" | "done" }>;
  actions: Action[];
  fields: Field[];
};
export type WorkflowDecision =
  | { kind: "reject"; message: string }
  | { kind: "input-required"; fields: Field[] }
  | { kind: "commit"; state: string; fields: Record<string, string> };
export type Workflow = {
  definition: WorkflowDefinition;
  decide(
    task: Task,
    action: string,
    input: Record<string, string>,
  ): WorkflowDecision;
};

export const missPolicies = ["skip", "run-once"] as const;
export type MissPolicy = (typeof missPolicies)[number];

export const taskEventKinds = [
  "task.created",
  "task.updated",
  "task.deleted",
] as const;
export type TaskEventKind = (typeof taskEventKinds)[number];

export const extensionCapabilityStatuses = [
  "active",
  "stub",
  "declared",
] as const;
export type ExtensionCapabilityStatus =
  (typeof extensionCapabilityStatuses)[number];

export const EXTENSIONS_CONTRACT = "extensions/1" as const;

export type CommandRegistration = {
  id: string;
  label: string;
  from?: string[];
};

export type ScheduleRegistration = {
  id: string;
  /**
   * Absolute ISO time, or when atKind is "field", the task field key holding ISO/wall time.
   */
  at: string;
  /** Defaults to "absolute". */
  atKind?: "absolute" | "field";
  timezone?: string;
  dedupeKey: string;
  onFire: {
    type: "action";
    commandId: string;
    /** Required for absolute jobs; field jobs fill taskId per armed task. */
    taskId?: string;
    input?: Record<string, string>;
  };
  missPolicy: MissPolicy;
};

export type LifecycleContribution = {
  activate?: boolean;
  ready?: boolean;
  quiesce?: boolean;
  dispose?: boolean;
};

export type UiContributionAction = {
  commandId: string;
  label: string;
};

export type UiContributionField = {
  key: string;
  label: string;
};

export type UiSlotRegistration = {
  id: string;
  slot: string;
  title?: string;
  body?: string;
  actions?: UiContributionAction[];
  fields?: UiContributionField[];
  order?: number;
};

export type ResolvedUiContribution = {
  id: string;
  slot: "task.detail";
  title: string;
  body?: string;
  actions: UiContributionAction[];
  fields: UiContributionField[];
  providerId: string;
  order?: number;
};

export type QueryFilterRegistration = {
  id: string;
  label: string;
};

export type QuerySortRegistration = {
  id: string;
  label: string;
  primary?: boolean;
};

export type ServiceRegistration = {
  id: string;
  version: string;
};

export type ExtensionContribution = {
  commands?: CommandRegistration[];
  fields?: Field[];
  beforeCommit?: boolean;
  events?: TaskEventKind[];
  schedules?: ScheduleRegistration[];
  lifecycle?: LifecycleContribution;
  uiSlots?: UiSlotRegistration[];
  queryFilters?: QueryFilterRegistration[];
  querySorts?: QuerySortRegistration[];
  diagnostics?: boolean;
  services?: ServiceRegistration[];
};

export type BeforeCommitInput = {
  task: Task;
  draft: Task;
  action: string;
  input: Record<string, string>;
  decision: Extract<WorkflowDecision, { kind: "commit" }>;
};

export type HookAnnotations = {
  annotations?: string[];
};

export type BeforeCommitResult =
  | {
      kind: "ok";
      fields?: Record<string, string>;
      state?: string;
      annotations?: string[];
    }
  | { kind: "reject"; message: string };

export type TaskEvent = {
  kind: TaskEventKind;
  task: Task;
  changedPaths: string[];
  revision: number;
  source: string;
};

export type TaskEventResult = void | HookAnnotations;

export type ExtensionCapability = {
  interfaceId: string;
  status: ExtensionCapabilityStatus;
  providerId: string;
  count: number;
};

export type ExtensionSummary = {
  contractVersion: typeof EXTENSIONS_CONTRACT | null;
  capabilities: ExtensionCapability[];
};

export const emptyContribution = (): ExtensionContribution => ({});

export type Plugin = {
  describe(): WorkflowDefinition;
  decide(data: {
    task: Task;
    action: string;
    input: Record<string, string>;
  }): WorkflowDecision;
  contribute?(): ExtensionContribution;
  lifecycleActivate?(data?: Record<string, never>): void | HookAnnotations;
  lifecycleReady?(data?: Record<string, never>): void | HookAnnotations;
  lifecycleQuiesce?(data?: Record<string, never>): void | HookAnnotations;
  lifecycleDispose?(data?: Record<string, never>): void | HookAnnotations;
  beforeCommit?(data: BeforeCommitInput): BeforeCommitResult;
  onTaskEvent?(data: TaskEvent): TaskEventResult;
};
"},{"ref":"src/server/evolution-domain.ts","hash":"d8f78c2f0f44bf582fc5cb4514b50bd76b218fd3f2516bfa4fb44acfaaac79a9","content":"import {
  BusinessAssertionError,
  verifyExtensions,
  type BusinessExtensions,
  type MemberAcceptanceCase,
} from "./business-verification.js";
import {
  unauthorizedMemberCommands,
  type AffectedAcceptance,
} from "./affected-acceptance.js";
import {
  assertWorkspaceCaseCoverage,
  requireAffectedAcceptanceForMemberChange,
  verifyViaIsolatedWorkspace,
  type WorkspaceAcceptanceCase,
  type WorkspaceCaseEvidence,
} from "./workspace-acceptance.js";
import {
  capture,
  planningInstruction,
  planningTools,
  readInvestigation,
  parsePlan,
  memberAcceptancePayload,
  type Investigation,
} from "./planning.js";
import type {
  PlanEvidence,
  InvestigatedPlan,
  ExperienceReport,
} from "../shared/assistant.js";
import type { Domain, Target } from "../evolution/evolution.js";
import { Workspace } from "./workspace.js";
import {
  AppError,
  type WorkflowDefinition,
  type WorkflowDecision,
  type Task,
} from "../shared/contracts.js";
import type { RuntimeLike, Version, VersionMember } from "../release/types.js";
import {
  composeCandidateMembers,
  memberEnabledDataImpact,
  resolveVersionMembers,
  validateCompositionMembers,
} from "../release/composition.js";
import {
  parseBusinessFiles,
  ProtectedCandidateError,
  CandidateValidationError,
  synthesizeMemberBundle,
} from "../release/business-bundle.js";
import type { BusinessBundle } from "../release/types.js";
import { hash } from "../release/storage.js";
import type { ExtensionContribution } from "./business/contracts.js";
import { emptyContribution } from "./business/contracts.js";
import { ExtensionRegistry } from "./extensions/registry.js";
import { resolveUiContributions } from "./extensions/ui-slots.js";

type Rule = {
  key: string;
  label: string;
  required: boolean;
  minLength: number;
  maxLength: number;
};
type MemberAddition = { pluginId: string; name: string };
type MemberUpgrade = { pluginId: string };
type Goal = {
  memberEnabled?: InvestigatedPlan["memberEnabled"];
  pluginId: string;
  name: string;
  fields: Rule[];
  extensions?: BusinessExtensions;
  memberCases?: MemberAcceptanceCase[];
  affectedAcceptance?: AffectedAcceptance;
  repairEvidence?: InvestigatedPlan["repairEvidence"];
  acceptanceRevision?: InvestigatedPlan["acceptanceRevision"];
  scope?: string[];
  capabilities?: InvestigatedPlan["capabilityChanges"];
  memberAdditions?: MemberAddition[];
  memberUpgrades?: MemberUpgrade[];
};
type SubmittedMember = { pluginId: string; source: string };
type DraftMemberChange =
  | {
      kind: "addition";
      planned: MemberAddition;
      submitted: SubmittedMember;
      draft: Version;
    }
  | {
      kind: "upgrade";
      planned: MemberUpgrade;
      submitted: SubmittedMember;
      draft: Version;
      prior: VersionMember;
      priorVersion: Version;
    };

function acceptanceDefinitionHash(goal: {
  fields: Rule[];
  extensions?: BusinessExtensions;
  memberCases?: MemberAcceptanceCase[];
}) {
  return hash({
    rules: goal.fields,
    extensions: goal.extensions,
    memberCases: goal.memberCases,
  });
}

function fieldContract(
  fields: { key: string; label: string; type: string; required?: boolean }[],
) {
  return fields.map((f) => ({
    key: f.key,
    label: f.label,
    type: f.type,
    required: !!f.required,
  }));
}

function workflowUnchangedForUpgrade(
  base: Version,
  goal: Goal,
  workflowSource: string,
  plannedAdditions: MemberAddition[],
  plannedUpgrades: MemberUpgrade[],
) {
  if (!plannedUpgrades.length || plannedAdditions.length || goal.extensions)
    return false;
  if (goal.pluginId !== base.pluginId) return false;
  if (workflowSource !== base.source) {
    if (!base.bundle || !workflowSource.startsWith('{"files":')) return false;
    const submittedFiles = parseBusinessFiles(
      (JSON.parse(workflowSource) as { files: unknown }).files,
    );
    const baselineFiles = Object.fromEntries(
      Object.entries(base.bundle.files).filter(([path]) => path !== "business/contract.ts"),
    );
    // JSON property/array order is transport formatting, not workflow source.
    // Every business path and source byte must still match the trusted baseline.
    if (!equal(submittedFiles, baselineFiles)) return false;
  }
  return equal(
    fieldContract(
      goal.fields.map((f) => ({
        key: f.key,
        label: f.label,
        type: "text",
        required: f.required,
      })),
    ),
    fieldContract((base.definition as WorkflowDefinition).fields),
  );
}

function splitCandidateSubmission(source: string): {
  workflowSource: string;
  members: SubmittedMember[];
} {
  if (!source.startsWith("{")) return { workflowSource: source, members: [] };
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(source) as Record<string, unknown>;
  } catch {
    return { workflowSource: source, members: [] };
  }
  const members = parseSubmittedMembers(parsed.members);
  if (Array.isArray(parsed.files))
    return {
      workflowSource: JSON.stringify({ files: parsed.files }),
      members,
    };
  if (typeof parsed.source === "string")
    return { workflowSource: parsed.source, members };
  if (members.length && !("files" in parsed) && !("source" in parsed))
    throw new ProtectedCandidateError("成员候选缺少工作流源码");
  return { workflowSource: source, members: [] };
}

function parseSubmittedMembers(value: unknown): SubmittedMember[] {
  if (value === undefined) return [];
