      throw new ProtectedCandidateError("同一候选不能同时新增与升级辅助成员");
    const plannedMemberIds = [
      ...plannedAdditions.map((m) => m.pluginId),
      ...plannedUpgrades.map((m) => m.pluginId),
    ].sort();
    const submittedIds = submittedMembers.map((m) => m.pluginId).sort();
