    let bundle: Version["bundle"];
    let definition: WorkflowDefinition;
    let recordSource = workflowSource;
    if (pinWorkflow) {
      code = base.code;
      bundle = base.bundle;
      definition = base.definition as WorkflowDefinition;
      recordSource = base.source;
    } else {
