            "business/entry.ts": workflowSource,
            "business/view.ts": `export default ${JSON.stringify({ title: goal.name, fields: goal.fields.map((f) => f.key) })};`,
            "business/config.json": "{}",
            "business/compatibility.json": '{"preserveUnknownFields":true}',
