          ...(goal.extensions?.actions ?? []).filter(
            (a) =>
              !(base.definition as WorkflowDefinition).actions.some(
                (old) => old.id === a.id,
              ),
          ),
        ],
        fields: [
          ...goal.fields.map((f) => ({
            key: f.key,
            label: f.label,
