{"pluginId":"tags","name":"标签","service":"plugin:tags","contractVersion":"extensions/1","source":"export default {
  contribute() {
    return {
      commands: [
        { id: "set-tag", label: "设置标签" }
      ],
      fields: [
        { key: "tag", label: "标签", type: "text" }
      ],
      beforeCommit: true
    };
  },
  decide(data) {
    if (data.action === "set-tag") {
      if (typeof data.input.tag !== "string") {
        return {
          kind: "input-required",
          fields: [{ key: "tag", label: "标签", type: "text" }]
        };
      }
      return {
        kind: "commit",
        state: data.task.state,
        fields: Object.assign({}, data.task.fields, { tag: data.input.tag })
      };
    }
    return { kind: "reject", message: "未知动作" };
  },
  beforeCommit(data) {
    if (data.decision.kind === "commit") {
      const fields = data.decision.fields || {};
      if (typeof fields.tag === "string") {
        const trimmed = fields.tag.trim();
        if (!trimmed) {
          return { kind: "reject", message: "标签不能为空白" };
        }
        return {
          kind: "ok",
          fields: Object.assign({}, fields, { tag: trimmed })
        };
      }
    }
    return { kind: "ok" };
  }
};
